SELECT `user_id`, `user_name`, `org_id`, sum( `work_duration` ) AS `work_duration`, sum( `work_pay_duration` ) AS `work_pay_duration`, sum( `rest_duration` ) AS `rest_duration`, sum( `rest_pat_duration` ) AS `rest_pat_duration`, sum( `fest_duration` ) AS `fest_duration`, sum( `fest_oat_duration` ) AS `fest_oat_duration` FROM `work_overtime_ledger`
`work_date` between #{param.period.begin} and #{param.period.end}
and `user_name` like concat('%',#{param.keyword},'%')
and `org_id` = #{param.orgId}

